  3	// Callback-style database access. Chapter 5 migrates this to UserRepository.
  4	export function findByEmail(email, callback) {
  5	  query('users', (u) => u.email === email && u.deleted_at === null, (err, rows) => {
  6	    if (err) return callback(err);
  7	    callback(null, rows[0] ?? null);
  8	  });
  9	}
 10	
 11	export function isActive(email, callback) {
 12	  findByEmail(email, (err, user) => {
 13	    if (err) return callback(err);
 14	    callback(null, Boolean(user));
 15	  });
 16	}
 17	// A deliberately tiny in-memory database with a callback API.
 18	// The callback style is the point: Chapter 5 migrates the service layer off it.
 19	
 20	const tables = {
 21	  users: [
 22	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
 23	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
 24	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
 25	  ],
 26	  orders: [
 27	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
 28	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
 29	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
 30	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
 31	  ],
 32	  payments: [
 33	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
 34	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
 35	  ],
 36	};
 37	
 38	export function reset() {
 39	  tables.users[2].deleted_at = '2026-01-04';
 40	  tables.orders.forEach((o) => { o.deleted_at = null; });
 41	}
 42	
 43	// Old-style callback query. Accepts a table name and a predicate.
 44	export function query(table, predicate, callback) {
 45	  setImmediate(() => {
 46	    const rows = tables[table];
 47	    if (!rows) return callback(new Error(`no such table: ${table}`));
 48	    try {
 49	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
 50	    } catch (err) {
 51	      callback(err);
 52	    }
 53	  });
 54	}
 55	
 56	export function update(table, id, patch, callback) {
 57	  setImmediate(() => {
 58	    const row = (tables[table] || []).find((r) => r.id === id);
 59	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
 60	    Object.assign(row, patch);
 61	    callback(null, { ...row });
 62	  });
 63	}
 64	// A router with no framework, so the project has an HTTP surface to survey
 65	// in Chapter 1's rate-limiting example without an Express dependency.
 66	import { listActiveUsers, findUser } from '../services/user-service.js';
 67	import { listOrdersForUser, totalPaidCents } from '../services/order-service.js';
 68	import { uncapturedTotalCents } from '../services/payment-service.js';
 69	
 70	export const routes = [
 71	  { method: 'GET', path: '/users', handler: (req, cb) => listActiveUsers(cb) },
 72	  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id), cb) },
 73	  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id), cb) },
 74	  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents(cb) },
 75	  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents(cb) },
 76	];
 77	
 78	export function listEndpoints() {
 79	  return routes.map((r) => `${r.method} ${r.path}`);
 80	}
 81	import { query, update } from '../db.js';
 82	
 83	// The repository pattern the project is migrating toward: promise-based,
 84	// one place per table, no query construction anywhere else.
 85	export class UserRepository {
 86	  findActive() {
 87	    return new Promise((resolve, reject) => {
 88	      query('users', (u) => u.deleted_at === null, (err, rows) =>
 89	        err ? reject(err) : resolve(rows));
 90	    });
 91	  }
 92	
 93	  findById(id) {
 94	    return new Promise((resolve, reject) => {
 95	      query('users', (u) => u.id === id, (err, rows) =>
 96	        err ? reject(err) : resolve(rows[0] ?? null));
 97	    });
 98	  }
 99	
100	  softDelete(id, when) {
101	    return new Promise((resolve, reject) => {
102	      update('users', id, { deleted_at: when }, (err, row) =>
103	        err ? reject(err) : resolve(row));
104	    });
105	  }
106	}
107	import { query, update } from '../db.js';
108	
109	// Callback-style database access. Chapter 5 migrates this to UserRepository.
110	export function listActiveUsers(callback) {
111	  query('users', (u) => u.deleted_at === null, callback);
112	}
113	
114	export function findUser(id, callback) {
115	  query('users', (u) => u.id === id, (err, rows) => {
116	    if (err) return callback(err);
117	    callback(null, rows[0] ?? null);
118	  });
119	}
120	
121	export function softDeleteUser(id, when, callback) {
122	  update('users', id, { deleted_at: when }, callback);
123	}
124	import { test } from 'node:test';
125	import assert from 'node:assert/strict';
126	import { findByEmail, isActive } from '../src/services/auth-service.js';
127	
128	test('findByEmail ignores soft-deleted users', (t, done) => {
129	  findByEmail('alan@example.com', (err, user) => {
130	    assert.equal(err, null);
131	    assert.equal(user, null);
132	    done();
133	  });
134	});
135	
136	test('isActive is true for a live user', (t, done) => {
137	  isActive('ada@example.com', (err, active) => {
138	    assert.equal(err, null);
139	    assert.equal(active, true);
140	    done();
141	  });
142	});

